revoke all on function politeshik_private.quarantined_schedule_id(text)from public,anon,authenticated;
create function politeshik_private.schedule_projection(p_path text,p_data jsonb)returns jsonb language sql immutable set search_path=''as $$
 select case when p_path='group/changes'then p_data else jsonb_build_object(
 'subjects',(select coalesce(jsonb_agg(jsonb_build_object('id',s->'id','name',s->'name','short',s->'short','needsReview',s->'needsReview')),'[]')from jsonb_array_elements(case when jsonb_typeof(p_data->'subjects')='array'then p_data->'subjects'else'[]'end)s),
 'teachers',(select coalesce(jsonb_agg(jsonb_build_object('id',t->'id','name',t->'name','subjectIds',t->'subjectIds')),'[]')from jsonb_array_elements(case when jsonb_typeof(p_data->'teachers')='array'then p_data->'teachers'else'[]'end)t),
 'schedule',p_data->'schedule','weeks',p_data->'weeks','pairs',p_data->'pairs','anchor',p_data->'anchor')end
$$;
revoke all on function politeshik_private.schedule_projection(text,jsonb)from public,anon,authenticated;
create function politeshik_private.schedule_projection_safe(p_data jsonb)returns boolean language sql immutable set search_path=''as $$
 select politeshik_private.schedule_text_safe(p_data::text)
 and not exists(select 1 from jsonb_array_elements(coalesce(p_data->'subjects','[]'))s where politeshik_private.quarantined_schedule_id(s->>'id')and not(s->>'name'='Предмет требует проверки'and s->>'needsReview'='true'))
 and not exists(select 1 from jsonb_array_elements(coalesce(p_data->'teachers','[]'))t where politeshik_private.quarantined_schedule_id(t->>'id'))
$$;
revoke all on function politeshik_private.schedule_projection_safe(jsonb)from public,anon,authenticated;
create table politeshik_private.schedule_write_audit(
 id bigint generated always as identity primary key,tenant_id text not null,path text not null,
 actor uuid,actor_role text,session_id text,operation text not null,
 before_data jsonb,after_data jsonb,created_at timestamptz not null default clock_timestamp()
);
create index schedule_audit_tenant_time on politeshik_private.schedule_write_audit(tenant_id,created_at desc);
alter table politeshik_private.schedule_write_audit enable row level security;
revoke all on politeshik_private.schedule_write_audit from public,anon,authenticated;
create policy schedule_audit_internal_only on politeshik_private.schedule_write_audit as restrictive for all to authenticated using(false)with check(false);
create function politeshik_private.guard_schedule_document()returns trigger language plpgsql security definer set search_path=''as $$
declare projected jsonb;begin
 if auth.uid()is not null and not public.is_admin()then raise exception 'Расписание и предметы меняют только администраторы своей группы'using errcode='42501';end if;
 if tg_op='DELETE'then return old;end if;
 projected:=politeshik_private.schedule_projection(new.path,new.data);
 if not politeshik_private.schedule_projection_safe(projected)then raise exception 'Сохранение остановлено: обнаружены подозрительные названия в расписании. Обновите приложение'using errcode='22023';end if;
 return new;
end $$;
revoke all on function politeshik_private.guard_schedule_document()from public,anon,authenticated;
create trigger trg_schedule_integrity before insert or update on public.docs for each row when(new.path in('group/config','group/extra','group/changes'))execute function politeshik_private.guard_schedule_document();
create trigger trg_schedule_integrity_delete before delete on public.docs for each row when(old.path in('group/config','group/extra','group/changes'))execute function politeshik_private.guard_schedule_document();
create function politeshik_private.audit_schedule_document()returns trigger language plpgsql security definer set search_path=''as $$
declare prev jsonb;next_data jsonb;tenant text;doc_path text;begin
 if tg_op<>'INSERT'then prev:=politeshik_private.schedule_projection(old.path,old.data);tenant:=old.tenant_id;doc_path:=old.path;end if;
 if tg_op<>'DELETE'then next_data:=politeshik_private.schedule_projection(new.path,new.data);tenant:=new.tenant_id;doc_path:=new.path;end if;
 if prev is distinct from next_data then
  insert into politeshik_private.schedule_write_audit(tenant_id,path,actor,actor_role,session_id,operation,before_data,after_data)
  values(tenant,doc_path,auth.uid(),case when politeshik_private.is_super_admin()then'superadmin'else public.member_role()end,
  auth.jwt()->>'session_id',tg_op,prev,next_data);
 end if;return null;
end $$;
revoke all on function politeshik_private.audit_schedule_document()from public,anon,authenticated;
create trigger trg_schedule_audit_insert after insert on public.docs for each row when(new.path in('group/config','group/extra','group/changes'))execute function politeshik_private.audit_schedule_document();
create trigger trg_schedule_audit_update after update on public.docs for each row when(new.path in('group/config','group/extra','group/changes'))execute function politeshik_private.audit_schedule_document();
create trigger trg_schedule_audit_delete after delete on public.docs for each row when(old.path in('group/config','group/extra','group/changes'))execute function politeshik_private.audit_schedule_document();

-- Preserve user material; only invalid academic labels are removed or quarantined.
do $$declare doc record;subjects jsonb;teachers jsonb;ids jsonb;begin
 for doc in select*from public.docs where path in('group/config','group/extra')and not politeshik_private.schedule_projection_safe(politeshik_private.schedule_projection(path,data))loop
  select coalesce(jsonb_agg(case when (politeshik_private.schedule_text_safe(coalesce(s->>'name','')||' '||coalesce(s->>'short',''))and not politeshik_private.quarantined_schedule_id(s->>'id'))then s
    else s||jsonb_build_object('name','Предмет требует проверки','short','Требует проверки','needsReview',true)end),'[]')into subjects
  from jsonb_array_elements(doc.data->'subjects')s
  where (politeshik_private.schedule_text_safe(coalesce(s->>'name','')||' '||coalesce(s->>'short',''))and not politeshik_private.quarantined_schedule_id(s->>'id'))or exists(
   select 1 from public.docs e cross join lateral jsonb_array_elements(coalesce(e.data->'homework','[]')||coalesce(e.data->'cards','[]')||coalesce(e.data->'notes','[]'))material
   where e.tenant_id=doc.tenant_id and e.path='group/extra'and material->>'subjectId'=s->>'id');
  select coalesce(jsonb_agg(s->>'id'),'[]')into ids from jsonb_array_elements(subjects)s;
  if doc.path='group/extra'then
   select coalesce(jsonb_agg(t||jsonb_build_object('subjectIds',(select coalesce(jsonb_agg(i),'[]')from jsonb_array_elements(coalesce(t->'subjectIds','[]'))i where ids@>jsonb_build_array(i)))),'[]')into teachers
   from jsonb_array_elements(coalesce(doc.data->'teachers','[]'))t where politeshik_private.schedule_text_safe(t->>'name')and not politeshik_private.quarantined_schedule_id(t->>'id');
   update public.docs set data=data||jsonb_build_object('subjects',subjects,'teachers',teachers,'updated',clock_timestamp()),updated=clock_timestamp()where tenant_id=doc.tenant_id and path=doc.path;
  else
   update public.docs set data=data||jsonb_build_object('subjects',subjects,'updated',clock_timestamp()),updated=clock_timestamp()where tenant_id=doc.tenant_id and path=doc.path;
  end if;
 end loop;
end $$;

-- Legacy setter had no actor authorization; keep this privilege exclusively with Arina.
create or replace function public.set_secret(p_key text,p_secret text)returns void language plpgsql security definer set search_path=''as $$
declare tenant text:=public.current_tenant();other_key text;other_hash text;begin
 if not politeshik_private.is_super_admin()then raise exception 'Доступно только Админу Арине'using errcode='42501';end if;
 if p_key is null or p_key not in('admin_pass','teacher_pass')then raise exception 'Неверный вид пароля';end if;
 if length(coalesce(p_secret,''))<8 or p_secret like'ПРИДУМАЙТЕ%'then raise exception 'Пароль слишком короткий';end if;
 other_key:=case when p_key='admin_pass'then'teacher_pass'else'admin_pass'end;
 select value into other_hash from public.settings where tenant_id=tenant and key=other_key;
 if other_hash is not null and other_hash=extensions.crypt(p_secret,other_hash)then raise exception 'Пароли должны различаться';end if;
 insert into public.settings(tenant_id,key,value)values(tenant,p_key,extensions.crypt(p_secret,extensions.gen_salt('bf',10)))
 on conflict(tenant_id,key)do update set value=excluded.value,updated=now();
 delete from public.admin_attempts where tenant_id=tenant;
end $$;
revoke all on function public.set_secret(text,text)from public,anon;
do $$begin if to_regprocedure('public.promote_admin(uuid)')is not null then execute 'revoke all on function public.promote_admin(uuid)from public,anon,authenticated';end if;end $$;
alter function public.doc_owner(text)set search_path='';
